//			call ArgExprCont and goto state 3
//	State 3
//		Accept
//	State 4
//		on  ident
//			shift and goto state 5
//	State 5
//		Accept
//		on  assign
//			shift and goto state 6
//		on  ellipsis, ident, kw_component, kw_enum, kw_func, kw_struct, kw_unit
