// Stmt grammar:
//
//	# ── Statements ────────────────────────────────────────────────────────────────
//	#
//	# Removed from keywords (now plain identifiers): output, timer, true, false, null.
//	# Emit statements and visual nodes both parse as VisualOrStmt.
//	# Scope/position enforcement is deferred to the IR lifter.
//	#
//	# Stmt first-token sets (all disjoint):
//	#   kw_import     → ImportDecl
//	#   kw_struct     → StructDecl
//	#   kw_enum       → EnumDecl
//	#   kw_unit       → UnitDecl
//	#   kw_const      → ConstDecl
//	#   kw_var        → VarDecl
//	#   kw_func       → FuncDecl  (excluded from StatementPrimary)
//	#   kw_component  → ComponentDecl
//	#   kw_return     → return statement
//	#   kw_break      → break statement
//	#   kw_continue   → continue statement
//	#   kw_if         → IfNode
//	#   kw_for        → ForNode
//	#   everything else → VisualOrStmt (visual nodes, calls, assignments, emits)
//
//	Stmt =
//	      ImportDecl
//	    | StructDecl
//	    | EnumDecl
//	    | UnitDecl
//	    | ConstDecl
//	    | VarDecl
//	    | FuncDecl
//	    | ComponentDecl
//	    | kw_return [ Expr ]
//	    | kw_break
//	    | kw_continue
//	    | IfNode
//	    | ForNode
//	    | VisualOrStmt
//	    .
//
//	State 0
//		on  kw_break, kw_continue
//			shift and goto state 1
//		on  kw_return
//			shift and goto state 2
//		on  kw_unit
//			call UnitDecl and goto state 1
//		on  kw_const
//			call ConstDecl and goto state 1
//		on  kw_var
//			call VarDecl and goto state 1
//		on  kw_func
//			call FuncDecl and goto state 1
//		on  kw_component
//			call ComponentDecl and goto state 1
//		on  float_lit, hash, i18n_str_full, i18n_str_start, i18n_triple_full, i18n_triple_start, ident, int_lit, lbrace, lbracket, lparen, raw_str, str_full, str_start, triple_full, triple_start, unit_lit
//			call VisualOrStmt and goto state 1
//		on  kw_if
//			call IfNode and goto state 1
//		on  kw_for
//			call ForNode and goto state 1
//		on  kw_import
//			call ImportDecl and goto state 1
//		on  kw_struct
//			call StructDecl and goto state 1
//		on  kw_enum
//			call EnumDecl and goto state 1
//	State 1
//		Accept
//	State 2
//		Accept
//		on  amp, bang, float_lit, hash, i18n_str_full, i18n_str_start, i18n_triple_full, i18n_triple_start, ident, int_lit, kw_const, kw_func, kw_import, kw_struct, lbrace, lbracket, lparen, minus, raw_str, star, str_full, str_start, triple_full, triple_start, unit_lit
